// Report Manager - missing namespace pages of the .NET API reference (docnet/).
// DocFX writes a page only for a namespace that declares types, but every type
// page links each segment of its namespace (Reportman.Hub.Client.DataChannel ->
// Reportman.html, Reportman.Hub.html, Reportman.Hub.Client.html), so the empty
// parents were 404s for every visitor and crawler that followed those links.
// This writes those parent pages, in DocFX's own layout, listing the namespaces
// below them. Re-run after regenerating the reference:
//   node doc/_build/docnet-namespaces.mjs
// Idempotent: it only (re)writes pages carrying its own marker, so a page that
// DocFX itself generates later is never overwritten.

import fs from 'node:fs';
import path from 'node:path';

const APIDIR = path.resolve(import.meta.dirname, '..', 'docnet', 'api');
const TEMPLATE = 'Reportman.Hub.Client.DataChannel.html'; // any DocFX namespace page
const MARKER = '<!-- generated by doc/_build/docnet-namespaces.mjs -->';

const toc = JSON.parse(fs.readFileSync(path.join(APIDIR, 'toc.json'), 'utf-8'));
const namespaces = toc.items.filter(i => i.type === 'Namespace').map(i => i.name).sort();

// Every proper prefix of a namespace whose page is missing (or is ours).
const owned = file => fs.existsSync(file) && fs.readFileSync(file, 'utf-8').includes(MARKER);
const parents = new Set();
for (const ns of namespaces) {
  const parts = ns.split('.');
  for (let n = 1; n < parts.length; n++) {
    const p = parts.slice(0, n).join('.');
    const file = path.join(APIDIR, p + '.html');
    if (!fs.existsSync(file) || owned(file)) parents.add(p);
  }
}

const counts = name => {
  const item = toc.items.find(i => i.name === name);
  const by = {};
  for (const t of item.items || []) by[t.type] = (by[t.type] || 0) + 1;
  const plural = { Class: 'classes', Struct: 'structs', Interface: 'interfaces', Enum: 'enums', Delegate: 'delegates' };
  const total = (item.items || []).length;
  const detail = Object.entries(by).map(([k, v]) => `${v} ${v === 1 ? k.toLowerCase() : (plural[k] || k.toLowerCase() + 's')}`);
  return `${total} ${total === 1 ? 'type' : 'types'}: ${detail.join(', ')}.`;
};

const template = fs.readFileSync(path.join(APIDIR, TEMPLATE), 'utf-8');
const EOL = template.includes('\r\n') ? '\r\n' : '\n';
const tplName = TEMPLATE.replace(/\.html$/, '');

for (const ns of [...parents].sort()) {
  const below = namespaces.filter(n => n.startsWith(ns + '.'));
  const summary = ns === 'Reportman'
    ? 'Root namespace of the Report Manager .NET libraries. It declares no types of its own: the reference is organised in the namespaces listed below.'
    : `This namespace declares no types of its own: its types are in the namespaces listed below.`;
  const desc = ns === 'Reportman'
    ? 'Report Manager .NET API reference: index of the Reportman namespaces (reporting engine, drawing, Windows Forms and WPF preview, designer, Hub client).'
    : `Report Manager .NET API reference: namespaces under ${ns}.`;
  const article = [
    `<article class="content wrap" id="_content" data-uid="${ns}">`,
    '',
    `  <h1 id="${ns.replace(/\./g, '_')}" data-uid="${ns}" class="text-break">Namespace ${ns}</h1>`,
    `  <div class="markdown level0 summary"><p>${summary}</p></div>`,
    '  <div class="markdown level0 conceptual"></div>',
    '  <div class="markdown level0 remarks"></div>',
    '    <h3 id="namespaces">',
    'Namespaces',
    '</h3>',
    ...below.flatMap(n => [
      `      <h4><a class="xref" href="${n}.html">${n}</a></h4>`,
      `      <section><p>${counts(n)}</p></section>`,
    ]),
    '',
    '',
    '</article>',
  ].join(EOL);

  const html = template
    .replace(/<article class="content wrap"[\s\S]*?<\/article>/, '@ARTICLE@')
    .split(`Namespace ${tplName}`).join(`Namespace ${ns}`)
    .replace(/(<meta name="title"[^>]*>)/, `$1${EOL}      <meta name="description" content="${desc}">`)
    .replace('<html>', `<html>${EOL}${MARKER}`);
  if (html.includes(tplName) || !html.includes('@ARTICLE@')) throw new Error(`${ns}: template not as expected`);
  fs.writeFileSync(path.join(APIDIR, ns + '.html'), html.replace('@ARTICLE@', () => article));
  console.log(`wrote docnet/api/${ns}.html (${below.length} namespaces)`);
}
